package xiaozhi.modules.diagnostics;

import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import xiaozhi.modules.airuntime.AiRuntimeControl;

/** Bounded read-only ledger evidence. No provider probes, corrective actions or notification delivery. */
@Service
public class AiOperationsDiagnosticsService {
    private final JdbcTemplate db;private final Environment env;private AiRuntimeControl runtime;
    public AiOperationsDiagnosticsService(JdbcTemplate db,Environment env){this.db=db;this.env=env;}
    @Autowired(required=false) public void setRuntime(AiRuntimeControl runtime){this.runtime=runtime;}
    private boolean flag(String name){return env.getProperty("features."+name,Boolean.class,false);}
    private static final String AUTH="'ACCOUNT_DISABLED','CONTROL_CHANGED','TOOL_AUTHORIZATION_EXPIRED','TOOL_SOURCE_CHANGED','TOOL_SOURCE_REVOKED','SPEECH_AUTHORIZATION_CHANGED','EXTERNAL_SOURCE_REVOKED','EXTERNAL_SOURCE_EXPIRED','EXTERNAL_TOKEN_REVOKED_OR_EXPIRED','EXTERNAL_MEDIA_BINDING_DENIED','EXTERNAL_MEDIA_AUTHORIZATION_REVOKED','EXTERNAL_MEDIA_AUTHORIZATION_EXPIRED','EXTERNAL_MEDIA_DISABLED','TOOL_AUTHORIZATION_REQUIRED'";
    private static final String CANCELED="'SPEECH_CANCELED','MATERIAL_CANCELED','SESSION_TERMINATED','SESSION_LIMIT','TOOL_RUN_CANCELED','REALTIME_TOOL_SUPERSEDED','REALTIME_INPUT_PAUSED','MATERIAL_PAUSE'";
    private static final String PROVIDER="'PROVIDER_AUTH','PROVIDER_ERROR','PROVIDER_UNAVAILABLE','PROVIDER_RATE_LIMIT','PROVIDER_TIMEOUT','SPEECH_PROVIDER_AUTH','SPEECH_PROVIDER_ERROR','SPEECH_PROVIDER_TIMEOUT','PERCEPTION_AUTH','PERCEPTION_ERROR','PERCEPTION_TIMEOUT'";
    private static final String TIMEOUT="'PROVIDER_TIMEOUT','SPEECH_PROVIDER_TIMEOUT','PERCEPTION_TIMEOUT','CONNECT_TIMEOUT','LEASE_EXPIRED','COMMAND_UNCONFIRMED','INJECTION_UNCONFIRMED','MATERIAL_CONTEXT_UNCONFIRMED','REALTIME_TOOL_TIME_BUDGET'";
    private static final String LIMITS="'TOOL_LIMIT_EXCEEDED','TOOL_CALL_BUDGET_EXCEEDED','TOOL_TIME_BUDGET_EXCEEDED','OUTPUT_LIMIT','OMNI_AUDIO_LIMIT','SPEECH_LIMIT_EXCEEDED','MATERIAL_LIMIT','REALTIME_TOOL_SESSION_BUDGET','REALTIME_TOOL_RESULT_LIMIT'";
    private static final String MEDIA="'MEDIA_INPUT_UNAVAILABLE','MATERIAL_INPUT_UNAVAILABLE','SPEECH_AUDIO_INVALID','TRANSCRIPTION_UNAVAILABLE'";
    private static final String CONFIG="'MODEL_MISMATCH','MODEL_CAPABILITY_UNAVAILABLE','BUSINESS_NOT_CONFIGURED','SPEECH_PROVIDER_NOT_CONFIGURED','MATERIAL_PERCEPTION_NOT_CONFIGURED','TOOL_CONTEXT_MISSING'";
    private record Flow(String name,boolean enabled,String from,String status,String error,String time,String created,String active,String queued,String expired,String completed,String unsuccessful,String workerKey,String model){}
    public Map<String,Object> snapshot(long administrator){
        db.queryForObject("SELECT 1",Integer.class);
        boolean c=flag("conversation-enabled"),rt=c&&flag("realtime-ai-enabled");
        List<Flow> definitions=List.of(
            new Flow("ai",c&&flag("ai-text-enabled"),"ai_run r","r.status","r.error_code","r.updated_at","r.created_at","r.status IN ('queued','running','streaming')","r.status='queued'","r.status IN ('running','streaming') AND (r.lease_expires_at IS NULL OR r.lease_expires_at<=CURRENT_TIMESTAMP(3))","r.status='completed'","r.status IN ('failed','canceled')","ai.worker.key","ai.execution.model"),
            new Flow("realtime",rt,"ai_realtime_session r","r.status","r.error_code","COALESCE(r.ended_at,r.created_at)","r.created_at","r.status IN ('pending','connecting','active')","r.status IN ('pending','connecting')","r.status IN ('connecting','active') AND (r.lease_expires_at IS NULL OR r.lease_expires_at<=CURRENT_TIMESTAMP(3))","r.status='ended'","r.status IN ('failed','expired','canceled')","realtime.worker.key","realtime.model"),
            new Flow("material",rt&&flag("realtime-materials-enabled"),"ai_realtime_material r LEFT JOIN ai_realtime_session s ON s.id=r.session_id","r.status","r.error_code","r.updated_at","r.created_at","r.status IN ('queued','dispatched','prepared')","r.status='queued'","r.status IN ('queued','dispatched','prepared') AND ((s.lease_expires_at IS NOT NULL AND s.lease_expires_at<=CURRENT_TIMESTAMP(3)) OR (r.status='dispatched' AND (r.dispatched_at IS NULL OR r.dispatched_at<=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 45 SECOND))) OR (r.status='prepared' AND (r.prepared_at IS NULL OR r.prepared_at<=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 15 SECOND))))","r.status='acknowledged'","r.status IN ('failed','canceled')","realtime.worker.key","realtime.materials.perception-model"),
            new Flow("speech",c&&flag("answer-speech-enabled"),"ai_answer_speech_job r LEFT JOIN ai_answer_speech_attempt a ON a.job_id=r.id AND a.attempt=r.attempt","r.status","r.error_code","r.updated_at","r.created_at","r.status IN ('queued','synthesizing')","r.status='queued'","r.status='synthesizing' AND (a.lease_expires_at IS NULL OR a.lease_expires_at<=CURRENT_TIMESTAMP(3) OR a.dispatched_at<=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 180 SECOND))","r.status='completed'","r.status IN ('failed','canceled')","answer-speech.worker.key","answer-speech.model"));
        Map<String,Object> flows=new LinkedHashMap<>();List<Map<String,Object>> alerts=new ArrayList<>();boolean degraded=false,unknown=false;
        for(Flow flow:definitions){var result=flow(flow,alerts);flows.put(flow.name,result);if("unknown".equals(result.get("state"))){unknown=true;degraded=true;}if("ok".equals(result.get("state"))&&((Number)result.get("expired_leases")).longValue()>0)degraded=true;}
        Map<String,Object> quota=runtime(administrator,definitions.stream().allMatch(Flow::enabled));if("unknown".equals(quota.get("state")))degraded=true;
        // A module can fail independently (missing table, timeout); distinguish that from total DB loss.
        if(unknown||"unknown".equals(quota.get("state")))db.queryForObject("SELECT 1",Integer.class);
        Map<String,Object> result=new LinkedHashMap<>();result.put("state",degraded||!alerts.isEmpty()?"degraded":"limited");result.put("readiness_scope","configuration_and_job_ledgers");result.put("generated_at",Instant.now().toString());result.put("window_seconds",Map.of("outcomes",3600,"alerts",900));result.put("database",Map.of("state","ok"));result.put("flows",flows);result.put("alerts",alerts);result.put("runtime_control",quota);return result;
    }
    private Map<String,Object> flow(Flow f,List<Map<String,Object>> alerts){
        Map<String,Object> config=Map.of("enabled",f.enabled,"worker_key_configured",env.getProperty(f.workerKey,"").length()>=32,"model_configured",!env.getProperty(f.model,defaultModel(f.name)).isBlank());
        if(!f.enabled)return Map.of("state","disabled","configuration",config);
        try {
            String e=f.error,systemFailure="("+f.unsuccessful+") AND "+f.status+"<>'canceled' AND ("+e+" IS NULL OR "+e+" NOT IN ("+AUTH+","+CANCELED+"))";
            String canceled="("+f.unsuccessful+") AND ("+f.status+"='canceled' OR "+e+" IN ("+AUTH+","+CANCELED+"))",recent=f.time+">=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 60 MINUTE)",queue="("+f.queued+") AND "+f.created+"<=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 60 SECOND)";
            String sql="SELECT "+sum(f.active,"active")+","+sum(f.queued,"queued")+","+sum(f.expired,"expired_leases")+","+sum(queue,"queue_overdue")+","+sum("("+f.completed+") AND "+recent,"completed")+","+sum(systemFailure+" AND "+recent,"failed")+","+sum(canceled+" AND "+recent,"canceled")+","+sum("("+f.unsuccessful+") AND "+f.status+"<>'canceled' AND "+e+" IN ("+PROVIDER+") AND "+f.time+">=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 15 MINUTE)","provider_failures_15m")+",MAX(CASE WHEN ("+f.completed+") AND "+recent+" THEN "+f.time+" END) AS last_success FROM "+f.from+" WHERE ("+f.active+") OR "+recent;
            var row=db.queryForMap(sql);String group="CASE WHEN "+e+" IN ("+AUTH+") THEN 'authorization' WHEN "+f.status+"='canceled' OR "+e+" IN ("+CANCELED+") THEN 'cancellation' WHEN "+e+" IN ("+TIMEOUT+") THEN 'timeout' WHEN "+e+" IN ("+PROVIDER+") THEN 'provider' WHEN "+e+" IN ("+LIMITS+") THEN 'limits' WHEN "+e+" IN ("+MEDIA+") THEN 'media' WHEN "+e+" IN ("+CONFIG+") THEN 'configuration' ELSE 'other' END";
            List<Map<String,Object>> groups=new ArrayList<>();for(var item:db.queryForList("SELECT "+group+" AS safe_group,COUNT(*) AS total FROM "+f.from+" WHERE ("+f.unsuccessful+") AND "+recent+" GROUP BY safe_group ORDER BY safe_group"))groups.add(Map.of("group",item.get("safe_group"),"count",number(item,"total")));
            Map<String,Object> result=new LinkedHashMap<>();result.put("state","ok");result.put("configuration",config);for(String field:List.of("active","queued","expired_leases","queue_overdue"))result.put(field,number(row,field));result.put("outcomes_60m",Map.of("completed",number(row,"completed"),"failed",number(row,"failed"),"canceled",number(row,"canceled")));result.put("error_groups_60m",groups);Object last=f.name.equals("realtime")?db.queryForObject("SELECT MAX(ended_at) FROM ai_realtime_turn WHERE kind='assistant' AND status='completed' AND ended_at>=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 60 MINUTE)",java.sql.Timestamp.class):row.get("last_success");result.put("observed_last_success_at",last==null?null:instant(last));
            alert(alerts,f.name,"LEASE_OVERDUE",number(row,"expired_leases"),"current_active_state");alert(alerts,f.name,"QUEUE_OVERDUE",number(row,"queue_overdue"),"current_active_state");long provider=number(row,"provider_failures_15m");if(provider>=3)alert(alerts,f.name,"PROVIDER_FAILURE_CONCENTRATION",provider,"terminal_outcomes_15m");return result;
        }catch(RuntimeException unavailable){return Map.of("state","unknown","configuration",config);}
    }
    private Map<String,Object> runtime(long actor,boolean dependenciesEnabled){if(runtime==null||!runtime.enabled())return Map.of("state","disabled");if(!dependenciesEnabled)return Map.of("state","unknown");try{var s=runtime.snapshot(actor);var l=s.limits();var u=s.usage();Map<String,Object> usage=new LinkedHashMap<>();usage.put("known_tokens",u.knownTokens());usage.put("token_reports",u.tokenReports());usage.put("unknown_token_reports",u.unknownTokenReports());usage.put("known_speech_characters",u.knownSpeechCharacters());usage.put("speech_reports",u.speechReports());usage.put("unknown_speech_reports",u.unknownSpeechReports());Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("enabled",s.enabled());snapshot.put("window_seconds",s.windowSeconds());snapshot.put("limits",Map.of("user_max_active",l.userMaxActive(),"service_max_active",l.serviceMaxActive(),"user_hourly_requests",l.userHourlyRequests(),"service_hourly_requests",l.serviceHourlyRequests()));snapshot.put("user",scope(s.user()));snapshot.put("service",scope(s.service()));snapshot.put("usage",usage);snapshot.put("service_limited",s.serviceLimited());snapshot.put("guarantee",s.guarantee());return Map.of("state","ok","usage_scope","current_administrator","snapshot",snapshot);}catch(RuntimeException unavailable){return Map.of("state","unknown");}}
    private static Map<String,Object> scope(AiRuntimeControl.Scope s){return s==null?null:Map.of("active",s.active(),"hourly_requests",s.hourlyRequests(),"remaining_active",s.remainingActive(),"remaining_hourly_requests",s.remainingHourlyRequests());}
    private static void alert(List<Map<String,Object>> target,String flow,String code,long count,String basis){if(count>0)target.add(Map.of("flow",flow,"code",code,"severity","warning","count",count,"window_seconds",900,"basis",basis));}
    private static String sum(String condition,String alias){return "COALESCE(SUM(CASE WHEN "+condition+" THEN 1 ELSE 0 END),0) AS "+alias;}
    private static long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
    private static String instant(Object timestamp){if(timestamp instanceof java.sql.Timestamp value)return value.toInstant().toString();if(timestamp instanceof java.time.LocalDateTime value)return value.toInstant(java.time.ZoneOffset.UTC).toString();if(timestamp instanceof Instant value)return value.toString();throw new IllegalStateException("Unknown ledger timestamp");}
    private static String defaultModel(String flow){return switch(flow){case "ai"->"qwen-flash";case "realtime"->"qwen3.8-omni-flash-realtime";case "speech"->"cosyvoice-v3.5-flash";default->"";};}
}
